__NUXT_JSONP__("/svet/mesto/maskat", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w){return {data:[{place:[{id:i,id_state:k,name:l,population:1604000,area:370,altitude:m,slug:n,information_chatgpt:"\u003Cp\u003EMaskat, hlavní město Ománu, je fascinující destinací spojující moderní architekturu s bohatou historií. Leží na pobřeží Ománského zálivu, oplývá krásnými plážemi a impozantním panoramatem pohoří Al Hajar.\u003C\u002Fp\u003E\n\u003Cp\u003EMezi významné pamětihodnosti patří Mešita sultána Kábúse, monumentální svatostánek postavený z bílého mramoru. Návštěvníci mohou obdivovat krásu Royal Opera House, kde se konají světově proslulé umělecké představení.\u003C\u002Fp\u003E\n\u003Cp\u003ETradiční atmosféru lze zakusit na Mutrah Souq, starém tržišti plném exotických výrobků a vonných koření. Nákupy vždy oživí atmosféru města, stejně jako návštěva historické čtvrti Old Muscat s pevností Al Jalali a Al Mirani.\u003C\u002Fp\u003E\n\u003Cp\u003EMaskat se může pyšnit moderním přístavem Port Sultan Qaboos, který nabízí luxusní námořní prostředí a odrazuje bohatství země. Pro milovníky přírody je nedalekým cílem horolezecký ráj Jebel Akhdar, známý svými terasovitými zahradami a olivovými sady.\u003C\u002Fp\u003E\n\u003Cp\u003EMěsto se chlubí také místními tradicemi, jako je například festival Muscat Festival, který představuje umění, kulturu a gastronomii. Ománská kuchyně pak láká návštěvníky chutěmi, jako jsou ochucená masa, ryby a rozmanité dezerty.\u003C\u002Fp\u003E\n\u003Cp\u003EMaskat spojuje minulost s přítomností, nabízí kontrastní zážitky od procházek starobylými uličkami po prozkoumávání moderních architektonických skvostů. To vše vytváří nezapomenutelný dojem pro ty, kteří si přejí objevovat krásy a poklady této ománské perly.\u003C\u002Fp\u003E",coordinates:[{latitude:23.61387,longitude:58.5922}],biggest:"yes",type_place:c,id_image_cover:a,id_image_hero:a,affiliate:[{name:o,value:p}],alerts:a,zoom:[{google:m,booking:11}],parking:a,information_author:a,importance:d,seo_tags:a}],imagePlace:[],placeState:[{tld:".om",name:"Omán",area:309500,population:5106626,slug:q,id_continent:g,information_chatgpt:"\u003Cp\u003EOmán je arabský stát nacházející se na východním pobřeží Arabského poloostrova. Má dlouhou historii jako obchodní cesta mezi Asii a Evropou a dodnes zachovává svůj kulturní dědictví a tradice, což činí z něj velmi zajímavé místo pro turisty.\u003C\u002Fp\u003E\n\u003Cp\u003EOmán nabízí mnoho možností pro turisty, včetně návštěvy národních parků a chráněných oblastí, kde mohou turisté obdivovat divokou přírodu a vodopády. Mezi nejznámější národní parky patří Al Hajar Mountains, Sharqiya Sands a Wadi Bani Khalid.\u003C\u002Fp\u003E\n\u003Cp\u003EOmán je také známý pro své historické památky, jako je například Sultan Qaboos Grand Mosque, jedna z největších mešit na světě, a zříceniny starých oáz, které odrážejí bohatou historii obchodu a kultury. Turisté se mohou také vydat na tradiční trhy a nákupní ulice, kde mohou zakoupit místní řemesla, koření a textilie.\u003C\u002Fp\u003E\n\u003Cp\u003EOmán má také překrásné pláže a čisté moře, které nabízí možnosti pro potápění, šnorchlování a další vodní sporty. Mezi nejpopulárnější pláže patří Qurum Beach, Al Bustan Beach a Al Mughsail Beach.\u003C\u002Fp\u003E\n\u003Cp\u003EOmán má také bohatou kuchyni s mnoha místními specialitami, jako je například šašlik a různé druhy rýže. Mezi další místní pochoutky patří například místní datle, mandlové sladkosti a arabská káva.\u003C\u002Fp\u003E\n\u003Cp\u003EPro turisty, kteří hledají kulturně bohaté a exotické cestování, je Omán určitě místem, které stojí za návštěvu. Zdejší lidé jsou velmi přátelští a pohostinní, což turistům poskytuje unikátní zážitek při poznávání této země a její kultury.\u003C\u002Fp\u003E",currency_code:"OMR",currency_name:"Ománský rial",money_prices:[{name:"Taxi (cena za km)",value:.2,date_update:e},{name:"Hlavní jídlo",value:3.5,date_update:e},{name:"Chleba",value:r,date_update:e},{name:"Mléko",value:s,date_update:e},{name:"Voda (500ml)",value:r,date_update:e},{name:"Espresso",value:t,date_update:e},{name:"Zmrzlina (jeden kopeček)",value:t,date_update:e},{name:"Pivo",value:1.5,date_update:e},{name:"Krabička cigaret",value:2.5,date_update:e},{name:"Bic Mac",value:a,date_update:e},{name:"Coca Cola (500ml)",value:s,date_update:e}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:h,date_update:f},{name:"Policie",value:h,date_update:f},{name:"Hasiči",value:h,date_update:f},{name:"Zdravotnická záchranná služba",value:h,date_update:f}],phone_prefix:"+968",coordinates:[{latitude:"21.4735329",longitude:"55.9754132"}],people_religion:[{name:"Ibádíjové",value:"75,0%",date_update:b},{name:"Muslimové (neibádíjové)",value:"24,5%",date_update:b},{name:"Křesťané",value:u,date_update:b},{name:"Hinduisté",value:"0,1%",date_update:b},{name:"Jiné náboženství\u002FNezjištěno",value:u,date_update:b},{name:"Bez vyznání",value:"0,0%",date_update:b}],people_nationality:[{name:"Ománci",value:"72,5%",date_update:b},{name:"Pákistánci",value:"8,4%",date_update:b},{name:"Indové",value:"7,4%",date_update:b},{name:"Bangladéšané",value:"3,3%",date_update:b},{name:"Filipínci",value:"1,5%",date_update:b},{name:"Egypťané",value:"1,3%",date_update:b},{name:"Jemenité",value:"1,2%",date_update:b},{name:"Jordánci",value:"0,9%",date_update:b},{name:"Další",value:"3,5%",date_update:b}],visitors_entry:[{name:"Občanský průkaz",value:"Občanský průkaz není platným dokladem pro vstup do Ománu. Je potřeba mít platný cestovní pas.",date_update:f},{name:"Cestovní pas",value:"Pro vstup do Ománu je potřeba mít platný cestovní pas. Pas musí být platný minimálně 6 měsíců od data vstupu do země.",date_update:f},{name:"Vízum",value:"Pro vstup do Ománu je pro většinu zemí potřeba mít vízum. Občané České republiky mohou získat vízum na letišti v Ománu při příletu, pokud mají platný cestovní pas a zpáteční letenku. Toto vízum je platné 30 dnů a může být prodlouženo o dalších 30 dnů. Pokud plánujete pobyt v Ománu delší než 30 dnů, je nutné vízum získat předem v omaniském konzulátu v České republice.",date_update:f},{name:"Očkování",value:"Pro vstup do Ománu není vyžadováno žádné specifické očkování. Nicméně, doporučuje se být očkován proti běžným chorobám jako jsou žloutenka A a B, tetanus, dávivá kašel, spalničky, příušnice a zarděnky.",date_update:f},{name:"Cestovní pojištění",value:"Cestovní pojištění není povinné, nicméně je doporučeno pro případ zdravotních komplikací nebo úrazů během pobytu v zemi.",date_update:f},{name:"Bezpečnostní situace",value:"Omán je považován za bezpečnou zemi s nízkou mírou kriminality. Nicméně se doporučuje být obezřetný a dodržovat základní bezpečnostní opatření, zejména v turistických oblastech.",date_update:f},{name:"Další informace",value:"V Ománu je třeba respektovat místní zvyklosti a kulturu, zejména v náboženských a konzervativních oblastech. Pokud se plánuje návštěva mešity, je nutné dodržovat striktní pravidla oblékání a chování. Je také důležité dodržovat zákazy alkoholu a veřejného pití.",date_update:f}],type_place:v,id_image_cover:j,id_image_hero:j,id_city_main:i,affiliate:[{name:o,value:p}],mpz:"OM",alerts:a,zoom:[{google:5,booking:6}],ids_neighboring_countries:[{id:w},{id:193},{id:245}],organization:a,apps:a,links:a,information_author:a,seo_tags:a,language_phrases:a,wall_sockets:a,id:k,facts_place:a}],imageState:[{id:j,name:q,source:"\u002Fworld\u002Fstates\u002F",date_create:"2023-05-03T20:14:00.749527+00:00",type:v,author:"pixabay.com"}],placeContinent:[{id:g,slug:"asie",name:"Asie",area:44580000,population:4630000000,population_density:104.03,number_states:50,information_chatgpt:"\u003Cp\u003E\u003Cb\u003EAsie\u003C\u002Fb\u003E se rozkládá na ploše téměř 44,6 milionu kilometrů čtverečních a žije zde více než 4,5 miliardy lidí, což představuje téměř 60 % celkového počtu obyvatel planety. Kontinent zahrnuje celkem 48 zemí, mezi největší patří \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Frusko\"\u003ERusko\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Fcina\"\u003EČína\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Findie\"\u003EIndie\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Fjaponsko\"\u003EJaponsko\u003C\u002Fa\u003E\u003C\u002Fb\u003E a \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Findonesie\"\u003EIndonésie\u003C\u002Fa\u003E\u003C\u002Fb\u003E.\u003C\u002Fp\u003E\n\u003Cp\u003E\u003Cb\u003EAsie\u003C\u002Fb\u003E je domovem mnoha významných světových kultur, jako jsou hinduismus, buddhismus, islám a taoismus. V každé zemi se můžeš setkat s odlišnými tradicemi, zvyky a jazyky. Mezi nejnavštěvovanější turistické destinace patří například \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Fjaponsko\"\u003EJaponsko\u003C\u002Fa\u003E\u003C\u002Fb\u003E s jeho futuristickými městy, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Fthajsko\"\u003EThajsko\u003C\u002Fa\u003E\u003C\u002Fb\u003E s bohatou kulturou a krásnými plážemi, nebo \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Findonesie\"\u003EIndonésie\u003C\u002Fa\u003E\u003C\u002Fb\u003E s neuvěřitelnou přírodou a množstvím ostrovů.\u003C\u002Fp\u003E\n\u003Cp\u003E\u003Cb\u003EAsie\u003C\u002Fb\u003E také nabízí mnoho kulturních a historických památek, jako je \u003Cb\u003EVelká čínská zeď\u003C\u002Fb\u003E, \u003Cb\u003ETaj Mahal\u003C\u002Fb\u003E v \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Findie\"\u003EIndii\u003C\u002Fa\u003E\u003C\u002Fb\u003E, buddhistické chrámy v \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Fthajsko\"\u003EThajsku\u003C\u002Fa\u003E\u003C\u002Fb\u003E a mnoho dalšího. Zajímavou zkušeností může být i návštěva tradičních trhů, kde se dají ochutnat místní speciality a nakoupit různé exotické produkty.\u003C\u002Fp\u003E\n\u003Cp\u003E\u003Cb\u003EAsie\u003C\u002Fb\u003E má však také své výzvy a problémy, jako jsou například růst městských oblastí, nedostatek vody a znečištění ovzduší. Mnoho zemí se snaží najít řešení těchto problémů a přizpůsobit se moderním trendům, aby mohly udržet krok s ostatními zeměmi světa.\u003C\u002Fp\u003E\n\u003Cp\u003EPokud tě láká cestování po \u003Cb\u003EAsii\u003C\u002Fb\u003E, měl by sis předem zajistit víza a informovat se o místních zvycích a tradicích. Rozhodně se ti však naskytne možnost prozkoumat jedinečnou kulturu, přírodu a historii tohoto fascinujícího kontinentu.\u003C\u002Fp\u003E\u003Cp\u003E\u003Cb\u003EAsie\u003C\u002Fb\u003E má také neuvěřitelně bohatou gastronomii, která se v jednotlivých zemích a regionech liší. Mezi nejznámější asijské pokrmy patří \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fjidlo\u002Fsushi\"\u003Esushi\u003C\u002Fa\u003E\u003C\u002Fb\u003E, různé druhy nudlí, \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fjidlo\u002Fcurry\"\u003Ecurry\u003C\u002Fa\u003E\u003C\u002Fb\u003E, \u003Cb\u003Edim sum\u003C\u002Fb\u003E, \u003Cb\u003Epho\u003C\u002Fb\u003E a další. Kromě toho se v \u003Cb\u003EAsii\u003C\u002Fb\u003E pěstuje mnoho exotických plodin, jako jsou \u003Cb\u003Eduriany\u003C\u002Fb\u003E, \u003Cb\u003Emangostany\u003C\u002Fb\u003E, \u003Cb\u003Erambutany\u003C\u002Fb\u003E a další ovoce, které můžeš ochutnat pouze zde.\n\u003C\u002Fp\u003E\u003Cp\u003E\n\u003Cb\u003EAsie\u003C\u002Fb\u003E je také známá svými svátky a tradicemi, jako je například \u003Cb\u003Ečínský Nový rok\u003C\u002Fb\u003E, \u003Cb\u003EDiwali\u003C\u002Fb\u003E v \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Findie\"\u003EIndii\u003C\u002Fa\u003E\u003C\u002Fb\u003E, nebo \u003Cb\u003ESongkran\u003C\u002Fb\u003E v \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Fthajsko\"\u003EThajsku\u003C\u002Fa\u003E\u003C\u002Fb\u003E,. Tyto svátky jsou většinou spojeny s různými rituály a zvyky, které se v průběhu staletí vyvinuly a jsou dodnes respektovány.\n\u003C\u002Fp\u003E\u003Cp\u003E\nKromě toho má \u003Cb\u003EAsie\u003C\u002Fb\u003E mnoho přírodních krás, jako jsou \u003Cb\u003EHimálaje\u003C\u002Fb\u003E, pouště \u003Cb\u003EGobi\u003C\u002Fb\u003E a \u003Cb\u003EThar\u003C\u002Fb\u003E, nebo tropické pralesy v \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Findonesie\"\u003EIndonésii\u003C\u002Fa\u003E\u003C\u002Fb\u003E a \u003Cb\u003E\u003Ca href=\"https:\u002F\u002Fwww.frytolnacestach.cz\u002Fsvet\u002Fstat\u002Fmalajsie\"\u003EMalajsii\u003C\u002Fa\u003E\u003C\u002Fb\u003E. V \u003Cb\u003EAsii\u003C\u002Fb\u003E se také nachází mnoho národních parků a chráněných oblastí, kde žijí ohrožené druhy zvířat, jako jsou \u003Cb\u003Etygři\u003C\u002Fb\u003E, \u003Cb\u003Epandy\u003C\u002Fb\u003E, \u003Cb\u003Esloni\u003C\u002Fb\u003E a další.\n\u003C\u002Fp\u003E\u003Cp\u003E\nZkrátka, \u003Cb\u003EAsie\u003C\u002Fb\u003E je kontinent plný kontrastů a neuvěřitelných zážitků, které stojí za to objevovat. Budeš-li mít příležitost navštívit některou z asijských zemí, neváhej a vydaj se na dobrodružnou cestu plnou nových objevů a nezapomenutelných zážitků.\u003C\u002Fp\u003E",coordinates:[{latitude:47.751076,longitude:92.475286}],type_place:"continent",id_image_cover:g,id_image_hero:g,zoom:[{google:w,booking:g}],information_author:a,seo_tags:a}],placesCities:[{id:1697,id_image_cover:a,importance:d,slug:"al-buraimi",type_place:c,name:"Al Buraimi"},{id:1691,id_image_cover:a,importance:d,slug:"barka",type_place:c,name:"Barka"},{id:1696,id_image_cover:a,importance:d,slug:"bidiyah",type_place:c,name:"Bidiyah"},{id:1692,id_image_cover:a,importance:d,slug:"izki",type_place:c,name:"Izki"},{id:1694,id_image_cover:a,importance:d,slug:"khasab",type_place:c,name:"Khasab"},{id:i,id_image_cover:a,importance:d,slug:n,type_place:c,name:l},{id:1693,id_image_cover:a,importance:d,slug:"nizwa",type_place:c,name:"Nizwa"},{id:1689,id_image_cover:a,importance:d,slug:"salala",type_place:c,name:"Salála"},{id:1690,id_image_cover:a,importance:d,slug:"suhar",type_place:c,name:"Suhár"},{id:1695,id_image_cover:a,importance:d,slug:"sur",type_place:c,name:"Sur"}],imagesCities:a}],fetch:{"OrganismsoPlaceTeaserSpotsComponent:0":{spots:[],images:a},"OrganismsoSidebarListComponent:0":{events:[],images:a}},mutations:[]}}(null,"01-2021","city","biggest","05-2022","05-2023",3,"999",1688,334,172,"Maskat",10,"maskat","booking",true,"oman",.1,.4,.5,"0,2%","state",2)));